class NationalIdentityCard {
    // Blank final fields: Assigned in constructor, then permanently locked
    private final String idNumber;
    private final String nationality;

    // Normal mutable field
    private String residentialAddress;

    public NationalIdentityCard(String id, String nation, String address) {
        this.idNumber = id;         // Locked forever!
        this.nationality = nation;   // Locked forever!
        this.residentialAddress = address;
    }

    public String getIdNumber() { return idNumber; }
    public String getNationality() { return nationality; }
    public String getAddress() { return residentialAddress; }

    public void updateAddress(String newAddress) {
        this.residentialAddress = newAddress;
    }

    // Attempting to reassign idNumber anywhere else fails compilation:
    // public void setId(String id) { this.idNumber = id; } -> COMPILE ERROR!
}

public class Main {
    public static void main(String[] args) {
        NationalIdentityCard card = new NationalIdentityCard("NAT-9012", "India", "New Delhi");
        System.out.println("ID: " + card.getIdNumber() + " (" + card.getNationality() + ")");

        // Address can change, ID can never change
        card.updateAddress("Mumbai");
        System.out.println("Updated Address: " + card.getAddress());
    }
}

