class MutableBox {
    public int value;
    public MutableBox(int v) { this.value = v; }
}

public class Main {
    public static void main(String[] args) {
        // Final reference variable:
        final MutableBox box = new MutableBox(10);

        // 1. CAN we mutate the internal state of the box? YES!
        box.value = 25;
        System.out.println("Mutated box value: " + box.value); // 25

        // 2. CAN we reassign the reference 'box' to point to a new object? NO!
        // box = new MutableBox(50); // COMPILE ERROR: cannot assign a value to final variable box
    }
}

