class CircleCalculator {
    public static final double PI = 3.14159;
    private final double radius;

    public CircleCalculator(double r) {
        this.radius = r > 0 ? r : 1.0;
    }

    public double calculateArea() {
        return PI * radius * radius;
    }

    public double calculateCircumference() {
        return 2 * PI * radius;
    }
}

public class Main {
    public static void main(String[] args) {
        CircleCalculator c = new CircleCalculator(5.0);
        System.out.println("Area: " + c.calculateArea());
    }
}

class TransactionToken {
    private final String tokenString;
    private final long createdAt;
    private final double authorizedAmount;

    public TransactionToken(String token, long time, double amount) {
        this.tokenString = token;
        this.createdAt = time;
        this.authorizedAmount = amount;
    }

    public String getTokenString() { return tokenString; }
    public long getCreatedAt() { return createdAt; }
    public double getAuthorizedAmount() { return authorizedAmount; }
}

public class Main {
    public static void main(String[] args) {
        TransactionToken t = new TransactionToken("TKN-ABC", 1000L, 250.0);
        System.out.println("Token " + t.getTokenString() + " authorized for $" + t.getAuthorizedAmount());
    }
}

